html:
{%- set tasks = frappe.get_all("Task",
        filters={"project": doc.name},
        fields=["name", "subject", "is_group", "exp_start_date", "exp_end_date",
                "duration", "progress", "status", "description", "lft"],
        order_by="lft asc", limit_page_length=0) -%}

{%- macro usdate(v) -%}
{%- if v -%}{%- set s = v|string -%}{{ s[5:7] }}/{{ s[8:10] }}/{{ s[2:4] }}{%- else -%}{%- endif -%}
{%- endmacro -%}

{%- set job = doc.project_name.split(" ")[0] -%}

<style>
  .ms-wrap { font-family: Arial, Helvetica, sans-serif; color: #000; font-size: 8.5pt; }
  .ms-head { display: flex; align-items: flex-end; justify-content: space-between;
             border-bottom: 2.5px solid #1f3864; padding-bottom: 6px; margin-bottom: 2px; }
  .ms-logo { font-size: 21pt; font-weight: bold; letter-spacing: .06em; color: #1f3864; }
  .ms-logo span { color: #c00000; }
  .ms-title { text-align: right; }
  .ms-title .t1 { font-size: 17pt; font-weight: bold; letter-spacing: .01em; }
  .ms-title .t2 { font-size: 9.5pt; font-weight: bold; letter-spacing: .05em; }
  .ms-title .t3 { font-size: 8pt; font-weight: bold; }

  table.ms { width: 100%; border-collapse: collapse; margin-top: 8px; }
  table.ms th, table.ms td { border: 0.6px solid #000; padding: 2.5px 4px; }
  table.ms th { background: #fff; font-size: 8pt; text-align: center; font-weight: bold; }
  table.ms td.n  { width: 3%;  text-align: center; color: #444; font-size: 7pt; border-left: none; }
  table.ms td.d  { width: 9%;  text-align: center; }
  table.ms td.dy { width: 6%;  text-align: center; }
  table.ms td.st { width: 8%;  text-align: center; }
  table.ms td.rm { width: 27%; font-size: 8pt; }
  table.ms tr.grp td { font-weight: bold; letter-spacing: .28em; font-size: 8.5pt; }
  table.ms td.task { padding-left: 10px; }
  .hp { font-weight: bold; }

  .ms-notes { margin-top: 10px; border: 0.6px solid #000; padding: 6px 8px; }
  .ms-notes .h { font-weight: bold; letter-spacing: .28em; font-size: 8.5pt; margin-bottom: 4px; }
  .ms-notes ol { margin: 0; padding-left: 16px; }
  .ms-notes li { font-size: 7.5pt; margin-bottom: 2px; }

  .ms-foot { margin-top: 10px; border-top: 1px solid #000; padding-top: 5px; font-size: 7.5pt; }
  .ms-foot .site { text-align: center; margin-top: 6px; font-weight: bold; color: #1f3864; }
</style>

<div class="ms-wrap">

  <div class="ms-head">
    <div class="ms-logo">MERC<span>&#9673;</span>URY</div>
    <div class="ms-title">
      <div class="t1">PROJECT SCHEDULE</div>
      <div class="t2">{{ doc.project_type == "External" and "VACUUM PUMP SYSTEM" or "PROJECT" }}</div>
      <div class="t3">Document: 103-{{ job }}</div>
    </div>
  </div>

  <table class="ms">
    <thead>
      <tr>
        <th></th>
        <th>Project Task</th>
        <th>Start</th>
        <th>Finish</th>
        <th>Days</th>
        <th>Status</th>
        <th>Remarks</th>
      </tr>
    </thead>
    <tbody>
      {%- set ns = namespace(row=0) -%}
      {%- for t in tasks -%}
      {%- set ns.row = ns.row + 1 -%}
      {%- if t.is_group -%}
        <tr class="grp">
          <td class="n">{{ ns.row }}</td>
          <td colspan="6">{{ t.subject }}</td>
        </tr>
      {%- else -%}
        {%- set rem = (t.description or "")|striptags|trim -%}
        <tr>
          <td class="n">{{ ns.row }}</td>
          <td class="task">{{ t.subject }}</td>
          <td class="d">{{ usdate(t.exp_start_date) }}</td>
          <td class="d">{{ usdate(t.exp_end_date) }}</td>
          <td class="dy">{{ t.duration or "" }}</td>
          <td class="st">{{ (t.progress or 0)|round(0)|int }}%</td>
          <td class="rm {% if 'Hold Point' in rem %}hp{% endif %}">{{ rem }}</td>
        </tr>
      {%- endif -%}
      {%- endfor -%}
    </tbody>
  </table>

  <div class="ms-notes">
    <div class="h">GENERAL NOTES</div>
    <ol>
      <li>Ship date shown is predicated on Mercury being released to manufacture by the RTM date shown above.</li>
      <li>Customer notification for WP inspections to be 7 days prior to scheduled event.</li>
      <li>Project schedule is subject to change upon receipt of customer comments which have impact design and/or scope of supply.</li>
      <li>Reference Mercury's Inspection &amp; Test Plan, latest approved revision, for fabrication hold points and other Quality requirements.</li>
    </ol>
  </div>

  <div class="ms-foot">
    {{ doc.notes or "" }}
    <div class="site">www.mercuryvacuum.com</div>
  </div>

</div>

{%- set proj = frappe.get_doc("Project", doc.project) -%}
{%- set so = frappe.get_all("Sales Order", filters={"project": doc.project},
        fields=["po_no"], limit_page_length=1) -%}
{%- set pono = so and so[0].po_no or "" -%}

<style>
  .pr { font-family: Arial, Helvetica, sans-serif; color: #000; font-size: 9.5pt; line-height: 1.45; }
  .pr-top { display: flex; justify-content: flex-end; border-bottom: 2.5px solid #1f3864;
            padding-bottom: 6px; }
  .pr-brand { text-align: right; }
  .pr-brand .logo { font-size: 20pt; font-weight: bold; letter-spacing: .05em; color: #1f3864; }
  .pr-brand .logo span { color: #c00000; }
  .pr-brand .tag { font-size: 7.5pt; font-style: italic; color: #1f3864; margin-bottom: 3px; }
  .pr-brand .addr { font-size: 7.5pt; color: #1f3864; line-height: 1.35; }

  .pr-band { display: flex; margin: 18px 0 22px; }
  .pr-band .left { background: #1f3864; color: #fff; padding: 16px 18px; width: 46%; }
  .pr-band .left .t1 { font-size: 20pt; font-weight: normal; line-height: 1.1; }
  .pr-band .left .t2 { font-size: 8.5pt; margin-top: 2px; }
  .pr-band .right { width: 54%; border: 0.6px solid #bbb; border-left: none; padding: 10px 14px; }
  .pr-band .right table { width: 100%; border-collapse: collapse; font-size: 8.5pt; }
  .pr-band .right td { padding: 2px 0; vertical-align: top; }
  .pr-band .right td.k { width: 32%; font-weight: bold; }
  .pr-band .right td.v { font-weight: bold; color: #1f3864; }

  .pr h3 { font-size: 9.5pt; font-weight: bold; margin: 16px 0 4px; letter-spacing: .01em; }
  .pr ol { margin: 0 0 0 4px; padding-left: 18px; }
  .pr ol li { margin-bottom: 3px; }
  .pr .attn { margin-bottom: 14px; font-size: 9.5pt; }
  .pr .sign { margin-top: 26px; }
  .pr .sign .name { font-weight: bold; }
  .pr .att { margin-top: 26px; }
  .pr .att .h { font-weight: bold; }
  .pr-foot { margin-top: 30px; border-top: 1px solid #1f3864; padding-top: 5px;
             text-align: center; font-size: 7.5pt; }
  .pr-foot .w { font-weight: bold; color: #1f3864; }
  .pr-foot .t { font-style: italic; color: #444; }
</style>

<div class="pr">

  <div class="pr-top">
    <div class="pr-brand">
      <div class="logo">MERC<span>&#9673;</span>URY</div>
      <div class="tag">Precision engineered.</div>
      <div class="addr">
        <b>Mercury Vacuum Technologies</b><br>
        2001 US Route 46 | Suite 310<br>
        Parsippany, NJ 07054 USA<br>
        (+1) 973.402.4880<br>
        www.mercuryvacuum.com
      </div>
    </div>
  </div>

  <div class="pr-band">
    <div class="left">
      <div class="t1">Progress Report</div>
      <div class="t2">Vacuum Pump Work in Progress Update</div>
    </div>
    <div class="right">
      <table>
        <tr><td class="k">Project:</td>  <td class="v">{{ proj.project_name.split("(")[-1].replace(")", "") if "(" in proj.project_name else proj.project_name }}</td></tr>
        <tr><td class="k">Customer:</td> <td class="v">{{ proj.customer or "" }}</td></tr>
        <tr><td class="k">PO#:</td>      <td class="v">{{ pono }}</td></tr>
        <tr><td class="k">Date:</td>     <td class="v">{{ doc.date.strftime("%B %d, %Y") if doc.date else "" }}</td></tr>
        <tr><td class="k">Document:</td> <td class="v">{{ doc.custom_document_no or "" }}</td></tr>
      </table>
    </div>
  </div>

  {%- if doc.custom_attention %}
  <div class="attn">Attention:<br>{{ doc.custom_attention | replace("\n", "<br>") }}</div>
  {%- endif %}

  {%- set sections = [
        ("A.", "ENGINEERING & SUBMITTALS", doc.custom_sec_a),
        ("B.", "PROCUREMENT", doc.custom_sec_b),
        ("C.", "METAL FABRICATION", doc.custom_sec_c),
        ("D.", "SYSTEM ASSEMBLY & TESTING", doc.custom_sec_d),
        ("E.", "SCHEDULE & UPCOMING MILESTONES", doc.custom_sec_e),
        ("F.", "PENDING ISSUES", doc.custom_sec_f) ] -%}
  {%- for letter, title, body in sections %}
    <h3>{{ letter }}&nbsp;&nbsp;{{ title }}</h3>
    {{ body or "" }}
  {%- endfor %}

  <div class="sign">
    Any questions or concerns regarding the points discussed above, please do not hesitate to contact us.
    <br><br>Respectfully submitted,<br><br><br>
    <span class="name">{{ doc.custom_signed_by or "" }}</span><br>
    Mercury Vacuum Technologies<br>
    {{ doc.custom_signed_email or "" }}
  </div>

  {%- if doc.custom_attachments %}
  <div class="att">
    <div class="h">ATTACHMENTS:</div>
    {{ doc.custom_attachments | replace("\n", "<br>") }}
  </div>
  {%- endif %}

  <div class="pr-foot">
    <div class="w">www.mercuryvacuum.com</div>
    <div class="t">Setting the standard of measure in vacuum performance.</div>
  </div>

</div>
